  ('hs0', 'high-signal', '1', 'How to set up your first home meeting: the checklist we use. Read it before your first one.', null, '{"type":"link","target":{"kind":"material","id":"lib-2"}}'::jsonb, seed_tmp.ts(-2583377), null, null),
