  ('d12b', 'dm-1-2', '2', 'Sounds good, talk tomorrow', null, null, seed_tmp.ts(-79577), null, null),
  ('cp1', 'carpool', '3', 'Starting a carpool thread for the Fall Weekend. Who needs a ride?', null, null, seed_tmp.ts(-77777), null, null),
